type ScoreEntry={score:number;tokens:number;seconds:number;date:string;level?:string};
const SCORE_KEY='physicsQuestHighScores';
const MUSIC_VOLUME_KEY='physicsQuestMusicVolumeV2';
const DEFAULT_MUSIC_VOLUME=.1;
const AVATAR_KEY='physicsQuestAvatar';
const readAvatar=()=>Math.max(0,AVATARS.findIndex(a=>a.key===localStorage.getItem(AVATAR_KEY))===-1?1:AVATARS.findIndex(a=>a.key===localStorage.getItem(AVATAR_KEY)));
const runNumber=(level:string)=>Number(localStorage.getItem('physicsQuestRun:'+level)??0)||0;
let feedbackContext:AudioContext|undefined;
const readScores=():ScoreEntry[]=>{try{return JSON.parse(localStorage.getItem(SCORE_KEY)??'[]') as ScoreEntry[]}catch{return[]}};
const saveScore=(entry:ScoreEntry)=>{const scores=[...readScores(),entry].sort((a,b)=>b.score-a.score).slice(0,5);localStorage.setItem(SCORE_KEY,JSON.stringify(scores));return scores};
const readMusicVolume=()=>Phaser.Math.Clamp(Number(localStorage.getItem(MUSIC_VOLUME_KEY)??DEFAULT_MUSIC_VOLUME),0,1);
const saveMusicVolume=(volume:number)=>{const value=Phaser.Math.Clamp(volume,0,1);localStorage.setItem(MUSIC_VOLUME_KEY,String(value));return value};
const tracks:Record<string,string>={menu:'mapping-the-zenith.mp3','EXO-1':'planet-x.mp3','EXO-2':'keplers-horizon.mp3','NS-1':'beneath-the-crust.mp3','NS-2':'under-the-stellar-current.mp3','CM-1':'conjugated-chains.mp3','CM-2':'electron-highway.mp3','PER-1':'laws-in-motion.mp3','PER-2':'eureka-loop.mp3'};
// Match measured integrated loudness to -20.3 LUFS without recompressing the MP3s.
const trackGain:Record<string,number>={menu:10**(-2/20),'EXO-1':10**(-4.6/20),'EXO-2':10**(-2.5/20),'NS-1':10**(-1.6/20),'NS-2':10**(-1.3/20),'CM-1':10**(-2.4/20),'CM-2':1,'PER-1':10**(-1.6/20),'PER-2':10**(-.8/20)};
type MusicVoice={audio:HTMLAudioElement;gain:number;fade:number;timer?:ReturnType<typeof setInterval>};
let currentTrack:MusicVoice|undefined;let outgoingTrack:MusicVoice|undefined;let musicVolume=readMusicVolume();
const applyMusicVolume=(voice:MusicVoice)=>{voice.audio.volume=musicVolume*voice.gain*voice.fade};
const setMusicVolume=(volume:number)=>{musicVolume=volume;if(currentTrack)applyMusicVolume(currentTrack);if(outgoingTrack)applyMusicVolume(outgoingTrack)};
const disposeMusic=(voice:MusicVoice)=>{clearInterval(voice.timer);voice.audio.pause();voice.audio.removeAttribute('src');voice.audio.load()};
const fadeMusic=(voice:MusicVoice,target:number,duration:number,done?:()=>void)=>{clearInterval(voice.timer);const start=performance.now(),initial=voice.fade;voice.timer=setInterval(()=>{const progress=Math.min(1,(performance.now()-start)/duration);voice.fade=initial+(target-initial)*progress;applyMusicVolume(voice);if(progress===1){clearInterval(voice.timer);done?.()}},33)};
const resumeMusic=()=>{const voice=currentTrack;if(voice&&voice.audio.paused)void voice.audio.play().catch(()=>{})};
const stopMusic=()=>{const voice=currentTrack;if(!voice)return; currentTrack=undefined;if(outgoingTrack)disposeMusic(outgoingTrack);outgoingTrack=voice;fadeMusic(voice,0,500,()=>{disposeMusic(voice);if(outgoingTrack===voice)outgoingTrack=undefined})};
const playMusic=(key:string)=>{stopMusic();const file=tracks[key];if(!file)return;const audio=new Audio();audio.loop=true;audio.preload='auto';const voice:MusicVoice={audio,gain:trackGain[key]??1,fade:0};currentTrack=voice;setMusicVolume(readMusicVolume());audio.addEventListener('playing',()=>{if(currentTrack===voice)fadeMusic(voice,1,750)},{once:true});audio.src=`assets/audio/${file}`;resumeMusic()};
window.addEventListener('pointerdown',resumeMusic);window.addEventListener('keydown',resumeMusic);

