  togglePause(){if(this.complete||(this as unknown as LearningScene).experimentOpen)return;this.paused=!this.paused;touchControls.show(true,this.paused);if(this.paused){this.physics.pause();this.showMessage('PAUSED — SELECT RESUME OR PRESS P',999999)}else{this.physics.resume();this.message.setAlpha(0)}}
