class ResearchScene extends LevelScene{
  zones:ResearchZone[]=[];palette=0x5ce1e6;variant=0;lab=false;
  createBackground(){
    this.cameras.main.setBackgroundColor(this.lab?'#11152d':'#071f25');
    const g=this.add.graphics().setDepth(0);for(const z of this.zones){g.fillStyle(z.color,.55).fillRect(z.start,0,z.end-z.start,GAME_HEIGHT);this.add.text(z.start+100,180,z.title,{fontFamily:'Arial, sans-serif',fontSize:'33px',fontStyle:'900',color:'#fff',stroke:'#07152f',strokeThickness:7});this.add.text(z.start+100,225,z.subtitle,{fontFamily:'Arial, sans-serif',fontSize:'17px',fontStyle:'900',color:'#b9efff',stroke:'#07152f',strokeThickness:4});}
    if(this.lab){for(let x=0;x<WORLD_WIDTH;x+=95){g.lineStyle(1,0xa7bafa,.12).lineBetween(x,260,x,580)}for(let y=260;y<580;y+=55)g.lineStyle(1,0xa7bafa,.12).lineBetween(0,y,WORLD_WIDTH,y);for(let x=180;x<WORLD_WIDTH;x+=620){g.fillStyle(0xc2defa,.18).fillRoundedRect(x,300,170,88,9);g.lineStyle(3,0x8deeff,.38).lineBetween(x+15,370,x+155,320);g.fillStyle(0xffd166,.6).fillCircle(x+155,320,6)}}else{for(let x=80;x<WORLD_WIDTH;x+=145){const y=320+Math.sin(x/300)*75;for(let i=0;i<4;i++){const px=x+i*23,py=y+(i%2)*24;g.lineStyle(4,this.palette,.22).lineBetween(px,py,px+23,y+((i+1)%2)*24);g.fillStyle(this.palette,.32).fillCircle(px,py,10);g.lineStyle(2,0xffffff,.13).strokeCircle(px,py,10)}}}
  }
  token(x:number,y:number){const t=this.tokens.create(x,y,'sample') as Phaser.Physics.Arcade.Image;t.setTint(this.palette).setData('baseY',y).setData('phase',Phaser.Math.FloatBetween(0,6.28));this.tweens.add({targets:t,angle:360,duration:1800,repeat:-1});return t}
  buildLevel(){
    GROUND_SEGMENTS.forEach(([a,b])=>this.ground(a,610,b-a));makeResearchLedges(this.variant).forEach(([x,y,m],i)=>{const p=this.platform(x,y,m);p.setTint(this.palette);const t=this.token(x,y-55);if(this.levelCode==='CM-2')t.setTint(i%2?0xff8bcf:0x7ce9ff)});
    CHECKPOINT_XS.forEach(x=>this.checkpointFlag(x,540,500));this.powerup(1550,535,'shield','shield');this.powerup(4100,535,'boost','gravity');this.powerup(6000,535,'speed','speed');
    const type=this.levelCode==='CM-1'?'molecular-disorder':this.levelCode==='CM-2'?'charge-trap':this.levelCode==='PER-1'?'measurement-noise':'misconception';[1650,3300,5000,7850].forEach((x,i)=>this.antagonist(x,535,i%2?'noiseEnemy':'glitchEnemy',type,14));
    this.scienceMilestones=this.zones.slice(1).filter(z=>z.lesson).map(z=>({x:z.start+180,key:z.lesson}));this.physics.add.staticImage(9020,520,'goal');this.add.text(9020,438,this.levelCode==='CM-2'?'ORGANIC SOLAR CELL':'RESEARCH STATION',{fontFamily:'Arial, sans-serif',fontSize:'16px',fontStyle:'900',color:'#ffd166',stroke:'#07152f',strokeThickness:5}).setOrigin(.5);
  }
}
